To implement the requested changes, I will update `components/OpeningStockModal.tsx`.

**Key Changes:**
1.  **Step 2 Portion Generation**: I will modify the `useEffect` hook that generates the `portions` state. It will now **only** generate portions based on the `selectedUnits` array from Step 1, strictly adhering to the user's configuration. I will remove the automatic inclusion of Base Unit and Container Unit unless they were explicitly selected in the "Product units" multi-select.
2.  **Step 2 Reporting Unit**: The dropdown for "Reporting unit" is already filtered by `portions`, so by restricting `portions`, this dropdown will automatically comply.
3.  **Save at Step 2**: I will add a `handleSaveFromStep2` function to allow saving the listing configuration (with 0 quantity) directly from the "Stock listing Information" step. I will add a "Save" button to the footer that appears only when `activeStep === 2`.

# Updated files:

## components/OpeningStockModal.tsx

```tsx
import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Theme, Shop, ProductDefinition, StockItem, ProductUnitDefinition } from '../types';
import Icon from './Icon';
import { availableProductUnits } from '../data';

interface OpeningStockModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (stockItem: StockItem) => void;
  theme: Theme;
  shops: Shop[];
  productDefinitions: ProductDefinition[];
}

interface Portion {
    id: string;
    name: string;
    quantity: number;
    price: number;
    isSelected: boolean;
}

const manufacturers = ['Unknown Manufacturer', 'Samsung', 'LG', 'Sony', 'Apple', 'Coca Cola', 'Pepsi', 'Unilever', 'Mukwano'];
const categories = ['Adhesives', 'Cosmetics', 'Electronics', 'Chemicals', 'Household', 'Industrial', 'Beverages', 'Personal care', 'Baby care'];
const suppliers = ['Unknown', 'Microvet Agroinputs Hub Mublo', 'Equacare Pharmacy', 'Korine Distributors Limited', 'Mickey Tablets and More UG'];
const warehouses = [
    { id: 101, name: 'Main Warehouse - Kampala' },
    { id: 102, name: 'Distribution Center - Jinja' },
    { id: 103, name: 'Storage Unit B' }
];

const Toggle = ({ label, description, checked, onChange, theme }: { label: string, description?: string, checked: boolean, onChange: (val: boolean) => void, theme: Theme }) => (
    <div className="flex items-center justify-between py-2">
        <div>
            <div className={`text-sm font-medium ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>{label}</div>
            {description && <div className={`text-xs ${theme === 'dark' ? 'text-slate-500' : 'text-slate-500'}`}>{description}</div>}
        </div>
        <button
            type="button"
            onClick={() => onChange(!checked)}
            className={`ml-4 relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none ${checked ? 'bg-yellow-500' : (theme === 'dark' ? 'bg-slate-600' : 'bg-slate-200')}`}
        >
            <span className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${checked ? 'translate-x-5' : 'translate-x-0'}`} />
        </button>
    </div>
);

const OpeningStockModal: React.FC<OpeningStockModalProps> = ({ isOpen, onClose, onSave, theme, shops, productDefinitions }) => {
    const [isClosing, setIsClosing] = useState(false);
    const [activeStep, setActiveStep] = useState(1);

    // Product Search State
    const [isProductDropdownOpen, setIsProductDropdownOpen] = useState(false);
    const [productSearch, setProductSearch] = useState('');
    const productDropdownRef = useRef<HTMLDivElement>(null);

    // Unit Selection State
    const [selectedUnits, setSelectedUnits] = useState<string[]>([]);
    const [unitDetails, setUnitDetails] = useState<Record<string, ProductUnitDefinition>>({});
    const [isUnitDropdownOpen, setIsUnitDropdownOpen] = useState(false);
    const unitDropdownRef = useRef<HTMLDivElement>(null);

    // Portions State for Step 2
    const [portions, setPortions] = useState<Portion[]>([]);

    // Form State
    const [formData, setFormData] = useState({
        // Step 1: Product Details
        locationType: 'Shop' as 'Shop' | 'Warehouse',
        locationId: '',
        productName: '',
        manufacturer: '',
        category: '',
        status: 'ACTIVE',
        // barcode removed from main input, moved to units
        baseUnit: '',
        baseQuantity: '',
        containerQuantity: '',
        containerUnit: '',
        description: '',
        hasBatchNumber: false,
        hasExpiryDate: false,

        // Step 2: Stock Listing Info
        customName: '',
        reportUnit: '',
        containerPortion: '',
        allowMix: false,
        listingRemarks: '', // Remarks

        // Step 3: Stock Information
        stockUnit: '',
        date: new Date().toISOString().split('T')[0],
        quantity: '',
        unitPrice: '', // Selling Price (can be overridden by portion price)
        buyingPrice: '', // Cost / Purchase Price
        batchNumber: '',
        expiryDate: '',
        supplier: 'Unknown',
        invoiceNumber: '',
    });

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (productDropdownRef.current && !productDropdownRef.current.contains(event.target as Node)) {
                setIsProductDropdownOpen(false);
            }
            if (unitDropdownRef.current && !unitDropdownRef.current.contains(event.target as Node)) {
                setIsUnitDropdownOpen(false);
            }
        };
        if (isProductDropdownOpen || isUnitDropdownOpen) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [isProductDropdownOpen, isUnitDropdownOpen]);

    useEffect(() => {
        if (isOpen) {
            setFormData({
                locationType: 'Shop',
                locationId: shops.length > 0 ? shops[0].id.toString() : '',
                productName: '',
                manufacturer: '',
                category: '',
                status: 'ACTIVE',
                baseUnit: '',
                baseQuantity: '',
                containerQuantity: '',
                containerUnit: '',
                description: '',
                hasBatchNumber: false,
                hasExpiryDate: false,
                customName: '',
                reportUnit: '',
                containerPortion: '',
                allowMix: false,
                listingRemarks: '',
                stockUnit: '',
                date: new Date().toISOString().split('T')[0],
                quantity: '',
                unitPrice: '',
                buyingPrice: '',
                batchNumber: '',
                expiryDate: '',
                supplier: 'Unknown',
                invoiceNumber: '',
            });
            setActiveStep(1);
            setPortions([]);
            setSelectedUnits([]);
            setUnitDetails({});
            setIsClosing(false);
        }
    }, [isOpen, shops]);

    // Initialize/Sync portions when entering Step 2
    useEffect(() => {
        if (activeStep === 2) {
            setPortions(prevPortions => {
                const newPortions: Portion[] = [];

                // Helper to find existing portion data to preserve price/selection
                const findExisting = (name: string) => prevPortions.find(p => p.name === name);

                // Only populate portions from selectedUnits in Step 1
                selectedUnits.forEach((u, idx) => {
                     if (u && !newPortions.some(p => p.name === u)) {
                         const existing = findExisting(u);
                         const details = unitDetails[u];
                         newPortions.push({ 
                             id: `unit-${idx}`, 
                             name: u, 
                             quantity: details?.quantity || 1, 
                             price: existing?.price || 0, 
                             isSelected: existing ? existing.isSelected : true 
                         });
                    }
                });

                return newPortions;
            });

            // Set default selection if none or invalid
            setFormData(prev => {
                 // Default container portion if not set or if current set value is no longer available
                 if (!prev.containerPortion || (selectedUnits.length > 0 && !selectedUnits.includes(prev.containerPortion))) {
                     return { ...prev, containerPortion: selectedUnits.length > 0 ? selectedUnits[0] : '' };
                 }
                 return prev;
            });
        }
    }, [activeStep, selectedUnits, unitDetails]);

    const handleClose = () => {
        setIsClosing(true);
        setTimeout(() => {
            onClose();
            setIsClosing(false);
        }, 300);
    };

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    // Specialized handler for stock price calculations
    const handleStockCalculation = (field: 'quantity' | 'unitPrice' | 'buyingPrice', value: string) => {
        setFormData(prev => {
            const newData = { ...prev, [field]: value };
            const qty = parseFloat(newData.quantity);
            const bPrice = parseFloat(newData.buyingPrice);
            const uPrice = parseFloat(newData.unitPrice);

            if (field === 'quantity') {
                // If qty changes:
                // Priority 1: If Buying Price (Total) exists, calc Unit Price (Cost allocation)
                if (!isNaN(bPrice) && !isNaN(qty) && qty !== 0) {
                    newData.unitPrice = (bPrice / qty).toFixed(2).replace(/\.00$/, '');
                } 
                // Priority 2: If Buying Price is empty but Unit Price exists, calc Buying Price
                else if (!isNaN(uPrice) && !isNaN(qty)) {
                    newData.buyingPrice = (uPrice * qty).toFixed(2).replace(/\.00$/, '');
                }
            } else if (field === 'buyingPrice') {
                // If Buying Price changes: Calc Unit Price
                if (!isNaN(qty) && qty !== 0 && !isNaN(bPrice)) {
                    newData.unitPrice = (bPrice / qty).toFixed(2).replace(/\.00$/, '');
                }
            } else if (field === 'unitPrice') {
                // If Unit Price changes: Calc Buying Price
                if (!isNaN(qty) && !isNaN(uPrice)) {
                    newData.buyingPrice = (uPrice * qty).toFixed(2).replace(/\.00$/, '');
                }
            }
            return newData;
        });
    };

    const handleProductSelect = (product: ProductDefinition) => {
        const units = product.definedUnits?.map(u => u.unitName) || (product.saleUnits ? product.saleUnits.split(',').map(s => s.trim()) : []);
        setSelectedUnits(units);

        const details: Record<string, ProductUnitDefinition> = {};
        if (product.definedUnits) {
            product.definedUnits.forEach(u => details[u.unitName] = u);
        } else {
             units.forEach(u => {
                 details[u] = { unitName: u, quantity: 1, barcode: '' };
             });
        }
        setUnitDetails(details);

        setFormData(prev => ({
            ...prev,
            productName: product.name,
            manufacturer: product.manufacturer,
            category: product.category || '',
            status: product.status || 'ACTIVE',
            baseUnit: product.baseUnit || '',
            baseQuantity: product.baseQuantity?.toString() || '',
            containerQuantity: product.containerQuantity?.toString() || '',
            containerUnit: product.containerUnit || '',
            description: product.remarks || '',
            hasBatchNumber: !!product.hasBatchNumber,
            hasExpiryDate: !!product.hasExpiryDate,
            customName: product.name, // Default custom name
        }));
        setIsProductDropdownOpen(false);
        setProductSearch('');
    };

    const handleUnitToggle = (unit: string) => {
        if (selectedUnits.includes(unit)) {
            setSelectedUnits(prev => prev.filter(u => u !== unit));
            const newDetails = { ...unitDetails };
            delete newDetails[unit];
            setUnitDetails(newDetails);
        } else {
            setSelectedUnits(prev => [...prev, unit]);
            setUnitDetails(prev => ({
                ...prev,
                [unit]: { unitName: unit, quantity: 1, barcode: '' }
            }));
        }
    };

    const handleUnitDetailChange = (unit: string, field: keyof ProductUnitDefinition, value: string | number) => {
        setUnitDetails(prev => ({
            ...prev,
            [unit]: {
                ...prev[unit],
                [field]: value
            }
        }));
    };

    const handleNext = () => {
        if (activeStep === 1) {
            if (!formData.productName || !formData.locationId) {
                alert("Please fill in Product Name and Location.");
                return;
            }
             // Validation for unit barcodes
            if (selectedUnits.length > 0) {
                const unitWithBarcode = selectedUnits.find(u => unitDetails[u]?.barcode && unitDetails[u]?.barcode.trim() !== '');
                if (!unitWithBarcode) {
                    alert("At least one selected unit must have a barcode.");
                    return;
                }
            }
        } else if (activeStep === 2) {
             if (!formData.reportUnit || !formData.containerPortion) {
                alert("Please select Report Unit and Product Unit.");
                return;
             }
             // Transfer selected portion price to main unit price if applicable
             const selectedPortion = portions.find(p => p.name === formData.containerPortion);
             if (selectedPortion && selectedPortion.price > 0) {
                 setFormData(prev => ({ ...prev, unitPrice: selectedPortion.price.toString() }));
             }
        }
        setActiveStep(prev => prev + 1);
    };

    const handleBack = () => {
        setActiveStep(prev => prev - 1);
    };

    const handleSaveFromStep2 = () => {
        if (!formData.reportUnit || !formData.containerPortion) {
            alert("Please select Report Unit and Product Unit.");
            return;
        }

        // Determine shop info
        let shopName = '';
        let shopId = 0;
        if (formData.locationType === 'Shop') {
            const shop = shops.find(s => s.id === parseInt(formData.locationId));
            if (shop) {
                shopName = shop.name;
                shopId = shop.id;
            }
        } else {
            const warehouse = warehouses.find(w => w.id === parseInt(formData.locationId));
            if (warehouse) {
                shopName = warehouse.name;
                shopId = warehouse.id;
            }
        }

        let mainBarcode = '';
        if (selectedUnits.length > 0) {
             const unitWithBarcode = selectedUnits.find(u => unitDetails[u]?.barcode && unitDetails[u]?.barcode.trim() !== '');
             if (unitWithBarcode) mainBarcode = unitDetails[unitWithBarcode].barcode;
        }

        const newStockItem: StockItem = {
            id: Date.now(),
            productName: formData.productName,
            productSN: `SN-${Date.now()}`,
            customName: formData.customName || formData.productName,
            barcode: mainBarcode,
            category: formData.category || 'Unknown',
            quantity: 0, // Default 0 for listing only
            unit: formData.baseUnit || 'Unit', // Default to base unit
            unitPrice: parseFloat(formData.unitPrice) || 0,
            currency: 'UGX',
            listedBy: 'Current User',
            listedOn: new Date().toISOString(),
            shopName: shopName,
            shopId: shopId,
            manufacturer: formData.manufacturer,
            baseUnit: formData.baseUnit || 'Unit',
            hasMultipleSaleUnits: selectedUnits.length > 0,
            reportUnit: formData.reportUnit,
            containerPortion: formData.containerPortion,
            allowMix: formData.allowMix,
            remarks: formData.listingRemarks,
            vatType: 'None',
            vatPercentage: 0,
        };

        onSave(newStockItem);
        handleClose();
    };

    const handleSave = () => {
        if (!formData.quantity || !formData.buyingPrice || !formData.stockUnit) {
            alert("Please fill in Stock Unit, Quantity and Purchase Price.");
            return;
        }

        // Determine shop ID/Name - if warehouse, map to a placeholder or treat as shop for now
        let shopName = '';
        let shopId = 0;

        if (formData.locationType === 'Shop') {
            const shop = shops.find(s => s.id === parseInt(formData.locationId));
            if (shop) {
                shopName = shop.name;
                shopId = shop.id;
            }
        } else {
            const warehouse = warehouses.find(w => w.id === parseInt(formData.locationId));
            if (warehouse) {
                shopName = warehouse.name;
                shopId = warehouse.id;
            }
        }

        // Determine main barcode from units
        let mainBarcode = '';
        if (selectedUnits.length > 0) {
             const unitWithBarcode = selectedUnits.find(u => unitDetails[u]?.barcode && unitDetails[u]?.barcode.trim() !== '');
             if (unitWithBarcode) mainBarcode = unitDetails[unitWithBarcode].barcode;
        }

        const newStockItem: StockItem = {
            id: Date.now(),
            productName: formData.productName,
            productSN: `SN-${Date.now()}`, 
            customName: formData.customName || formData.productName,
            barcode: mainBarcode,
            category: formData.category || 'Unknown',
            quantity: parseFloat(formData.quantity),
            unit: formData.stockUnit,
            unitPrice: parseFloat(formData.unitPrice) || 0, 
            currency: 'UGX', // Default currency
            listedBy: 'Current User',
            listedOn: new Date(formData.date).toISOString(),
            shopName: shopName,
            shopId: shopId,
            manufacturer: formData.manufacturer,
            baseUnit: formData.baseUnit || 'Unit',
            hasMultipleSaleUnits: selectedUnits.length > 0,
            reportUnit: formData.reportUnit,
            containerPortion: formData.containerPortion,
            allowMix: formData.allowMix,
            remarks: `${formData.listingRemarks} ${formData.invoiceNumber ? `(Inv: ${formData.invoiceNumber})` : ''}`,
            vatType: 'None', 
            vatPercentage: 0,
        };

        onSave(newStockItem);
        handleClose();
    };

    const filteredProducts = productDefinitions.filter(p => 
        p.name.toLowerCase().includes(productSearch.toLowerCase()) || 
        p.sn.toLowerCase().includes(productSearch.toLowerCase())
    );

    if (!isOpen && !isClosing) return null;

    const inputClass = `w-full rounded-md border shadow-sm px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200 placeholder-slate-500' : 'bg-white border-slate-300 text-slate-900 placeholder-slate-400'}`;
    const labelClass = `block text-sm font-medium mb-1 ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`;

    const StepsHeader = () => (
        <div className={`flex items-center gap-6 px-6 border-b ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`}>
            {['Product details', 'Stock listing Information', 'Stock Information'].map((stepName, index) => {
                const stepNum = index + 1;
                const isActive = activeStep === stepNum;
                const isCompleted = activeStep > stepNum;

                return (
                    <div 
                        key={stepNum}
                        className={`pb-3 pt-4 text-sm font-medium border-b-2 transition-colors flex items-center gap-2 cursor-default ${
                            isActive 
                                ? 'border-yellow-500 text-slate-900 dark:text-slate-100' 
                                : isCompleted 
                                    ? 'border-transparent text-green-600 dark:text-green-400' 
                                    : 'border-transparent text-slate-500 dark:text-slate-400'
                        }`}
                    >
                        <span className={`flex items-center justify-center w-5 h-5 rounded-full text-xs font-bold ${
                            isActive 
                                ? 'bg-yellow-500 text-slate-900' 
                                : isCompleted 
                                    ? 'bg-green-600 text-white' 
                                    : 'bg-slate-200 dark:bg-slate-700 text-slate-500 dark:text-slate-400'
                        }`}>
                            {isCompleted ? <Icon name="check-circle" className="w-3 h-3" /> : stepNum}
                        </span>
                        {stepName}
                    </div>
                )
            })}
        </div>
    );

    return (
        <div className={`fixed inset-0 bg-black z-[80] flex justify-center items-center p-4 transition-opacity duration-300 ${isOpen && !isClosing ? 'opacity-100 bg-opacity-50' : 'opacity-0'}`}>
            <div className={`${theme === 'dark' ? 'bg-slate-900' : 'bg-white'} rounded-lg shadow-xl w-full max-w-3xl flex flex-col transition-all duration-300 ease-in-out ${isOpen && !isClosing ? 'scale-100 opacity-100' : 'scale-95 opacity-0'} max-h-[90vh]`}>
                <div className={`flex justify-between items-center p-6 border-b ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`}>
                    <h2 className={`text-xl font-bold ${theme === 'dark' ? 'text-slate-100' : 'text-slate-900'}`}>
                        New Product
                    </h2>
                    <button onClick={handleClose} className={`${theme === 'dark' ? 'text-slate-400 hover:text-slate-200' : 'text-slate-500 hover:text-slate-800'}`}>
                        <Icon name="x-mark" className="h-6 w-6" />
                    </button>
                </div>

                <StepsHeader />

                <div className="p-6 space-y-6 overflow-y-auto flex-1">

                    {/* Step 1: Product Details */}
                    {activeStep === 1 && (
                        <div className="space-y-6">
                            {/* Top Bar with Existing Product Search */}
                             <div className="flex justify-between items-center">
                                 <h3 className={`text-sm font-bold uppercase tracking-wider ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>General Info</h3>
                                 <button 
                                    className={`px-4 py-1.5 text-xs font-medium border rounded-md transition-colors flex items-center gap-2 ${theme === 'dark' ? 'border-slate-600 hover:bg-slate-800 text-yellow-500' : 'border-slate-300 hover:bg-slate-50 text-yellow-600'}`}
                                    onClick={() => setIsProductDropdownOpen(true)}
                                 >
                                    <Icon name="search" className="h-3 w-3" /> Load Existing Product
                                 </button>
                             </div>

                             {/* Product Search Dropdown Overlay */}
                             {isProductDropdownOpen && (
                                <div className="relative" ref={productDropdownRef}>
                                    <div className={`absolute top-0 left-0 w-full z-20 rounded-md shadow-lg max-h-60 overflow-auto border ${theme === 'dark' ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-300'}`}>
                                        <div className="p-2 sticky top-0 bg-inherit z-10 border-b border-inherit">
                                            <input 
                                                type="text" 
                                                placeholder="Search product definition..." 
                                                className={`w-full px-2 py-1 text-sm rounded border focus:outline-none focus:ring-1 focus:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-700 border-slate-600 text-white' : 'bg-slate-50 border-slate-300'}`}
                                                value={productSearch}
                                                onChange={(e) => setProductSearch(e.target.value)}
                                                autoFocus
                                            />
                                        </div>
                                        {filteredProducts.map(p => (
                                            <div 
                                                key={p.id} 
                                                className={`px-3 py-2 text-sm cursor-pointer ${theme === 'dark' ? 'hover:bg-slate-700 text-slate-200' : 'hover:bg-slate-100 text-slate-800'}`}
                                                onClick={() => handleProductSelect(p)}
                                            >
                                                <div className="font-medium">{p.name}</div>
                                                <div className={`text-xs ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>{p.manufacturer}</div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                             )}

                            <div className="grid grid-cols-1 gap-4">
                                <div>
                                    <label className={labelClass}>Product Name<span className="text-red-500">*</span></label>
                                    <input type="text" name="productName" value={formData.productName} onChange={handleInputChange} className={inputClass} />
                                </div>
                                <div>
                                    <label className={labelClass}>Manufacturer<span className="text-red-500">*</span></label>
                                    <select name="manufacturer" value={formData.manufacturer} onChange={handleInputChange} className={inputClass}>
                                        <option value="">Select Manufacturer</option>
                                        {manufacturers.map(m => <option key={m} value={m}>{m}</option>)}
                                    </select>
                                </div>

                                {/* Location Row */}
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div>
                                        <label className={labelClass}>Location Type</label>
                                        <select 
                                            name="locationType" 
                                            value={formData.locationType} 
                                            onChange={(e) => setFormData(prev => ({ ...prev, locationType: e.target.value as any, locationId: '' }))} 
                                            className={inputClass}
                                        >
                                            <option value="Shop">Shop</option>
                                            <option value="Warehouse">Warehouse</option>
                                        </select>
                                    </div>
                                    <div>
                                        <label className={labelClass}>{formData.locationType}<span className="text-red-500">*</span></label>
                                        <select name="locationId" value={formData.locationId} onChange={handleInputChange} className={inputClass}>
                                            <option value="">Select {formData.locationType}</option>
                                            {formData.locationType === 'Shop' 
                                                ? shops.map(s => <option key={s.id} value={s.id}>{s.name}</option>)
                                                : warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)
                                            }
                                        </select>
                                    </div>
                                </div>

                                {/* Category & Status Row */}
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div>
                                        <label className={labelClass}>Category<span className="text-red-500">*</span></label>
                                        <select name="category" value={formData.category} onChange={handleInputChange} className={inputClass}>
                                            <option value="">Select Category</option>
                                            {categories.map(c => <option key={c} value={c}>{c}</option>)}
                                        </select>
                                    </div>
                                    <div>
                                        <label className={labelClass}>Production status</label>
                                        <select name="status" value={formData.status} onChange={handleInputChange} className={inputClass}>
                                            <option value="ACTIVE">Active</option>
                                            <option value="INACTIVE">Inactive</option>
                                        </select>
                                    </div>
                                </div>
                            </div>

                            <div className="border-t pt-4 mt-2">
                                <h4 className={`text-sm font-bold mb-3 ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>Metrics</h4>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                                    <div>
                                        <label className={labelClass}>Base Unit<span className="text-red-500">*</span></label>
                                        <select name="baseUnit" value={formData.baseUnit} onChange={handleInputChange} className={inputClass}>
                                            <option value="">Select Unit</option>
                                            {availableProductUnits.map(u => <option key={u} value={u}>{u}</option>)}
                                        </select>
                                    </div>
                                    <div>
                                        <label className={labelClass}>Base quantity<span className="text-red-500">*</span></label>
                                        <input type="number" name="baseQuantity" value={formData.baseQuantity} onChange={handleInputChange} className={inputClass} />
                                    </div>
                                    <div>
                                        <label className={labelClass}>Container quantity</label>
                                        <input type="number" name="containerQuantity" value={formData.containerQuantity} onChange={handleInputChange} className={inputClass} />
                                    </div>
                                    <div>
                                        <label className={labelClass}>Container Unit</label>
                                        <select name="containerUnit" value={formData.containerUnit} onChange={handleInputChange} className={inputClass}>
                                            <option value="">Select Unit</option>
                                            {availableProductUnits.map(u => <option key={u} value={u}>{u}</option>)}
                                        </select>
                                    </div>
                                </div>

                                {/* Multi-select Product Units */}
                                <div className="mb-4">
                                    <label className={labelClass}>Product units<span className="text-red-500">*</span></label>
                                    <div className="relative" ref={unitDropdownRef}>
                                        <div 
                                            className={`w-full rounded-md border shadow-sm px-3 py-2 text-sm min-h-[38px] flex flex-wrap gap-2 items-center cursor-pointer focus-within:ring-1 focus-within:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600' : 'bg-white border-slate-300'}`}
                                            onClick={() => setIsUnitDropdownOpen(!isUnitDropdownOpen)}
                                        >
                                            {selectedUnits.length === 0 && <span className="text-gray-400">Select units</span>}
                                            {selectedUnits.map(unit => (
                                                <span key={unit} className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-yellow-100 text-yellow-800 border border-yellow-200">
                                                    {unit}
                                                    <button 
                                                        type="button"
                                                        onClick={(e) => { e.stopPropagation(); handleUnitToggle(unit); }}
                                                        className="ml-1 text-yellow-900 hover:text-yellow-600 focus:outline-none"
                                                    >
                                                        <Icon name="x-mark" className="h-3 w-3" />
                                                    </button>
                                                </span>
                                            ))}
                                            <div className="ml-auto"><Icon name="chevron-down" className="h-4 w-4 text-gray-400" /></div>
                                        </div>
                                        {isUnitDropdownOpen && (
                                            <div className={`absolute z-10 mt-1 w-full rounded-md shadow-lg max-h-48 overflow-auto border ${theme === 'dark' ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-300'}`}>
                                                {availableProductUnits.map(unit => (
                                                    <div 
                                                        key={unit} 
                                                        className={`px-3 py-2 cursor-pointer text-sm flex items-center justify-between ${theme === 'dark' ? 'hover:bg-slate-700 text-slate-200' : 'hover:bg-slate-100 text-slate-800'} ${selectedUnits.includes(unit) ? 'bg-yellow-500/10' : ''}`}
                                                        onClick={() => handleUnitToggle(unit)}
                                                    >
                                                        {unit}
                                                        {selectedUnits.includes(unit) && <Icon name="check-circle" className="h-4 w-4 text-yellow-500" />}
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>

                                {/* Dynamic Unit Inputs */}
                                {selectedUnits.length > 0 && (
                                    <div className="space-y-3 mb-4">
                                        <div className="grid grid-cols-3 gap-4">
                                            <label className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>Unit name*</label>
                                            <label className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>Quantity*</label>
                                            <label className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>Barcode</label>
                                        </div>
                                        {selectedUnits.map(unit => (
                                            <div key={unit} className="grid grid-cols-3 gap-4">
                                                <input 
                                                    type="text" 
                                                    value={unitDetails[unit]?.unitName || unit} 
                                                    onChange={(e) => handleUnitDetailChange(unit, 'unitName', e.target.value)}
                                                    className={inputClass} 
                                                />
                                                <input 
                                                    type="number" 
                                                    value={unitDetails[unit]?.quantity || 1} 
                                                    onChange={(e) => handleUnitDetailChange(unit, 'quantity', parseFloat(e.target.value) || 0)}
                                                    className={inputClass} 
                                                />
                                                <input 
                                                    type="text" 
                                                    value={unitDetails[unit]?.barcode || ''} 
                                                    onChange={(e) => handleUnitDetailChange(unit, 'barcode', e.target.value)}
                                                    className={inputClass} 
                                                    placeholder="Barcode"
                                                />
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>

                            {/* Tracking Section */}
                            <div>
                                <h3 className={`text-sm font-bold mb-4 border-b pb-2 ${theme === 'dark' ? 'text-slate-200 border-slate-700' : 'text-slate-800 border-slate-200'}`}>Tracking</h3>
                                <div className="space-y-4 mb-4">
                                     <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                        <Toggle 
                                            label="Batch Number Tracking" 
                                            description="Enable to track batch #."
                                            checked={formData.hasBatchNumber} 
                                            onChange={(val) => setFormData(prev => ({...prev, hasBatchNumber: val}))} 
                                            theme={theme} 
                                        />
                                        <Toggle 
                                            label="Expiry Date Tracking" 
                                            description="Enable to track expiry."
                                            checked={formData.hasExpiryDate} 
                                            onChange={(val) => setFormData(prev => ({...prev, hasExpiryDate: val}))} 
                                            theme={theme} 
                                        />
                                    </div>
                                </div>
                            </div>

                            <div>
                                <label className={labelClass}>Description</label>
                                <textarea name="description" value={formData.description} onChange={handleInputChange} className={inputClass} rows={3} placeholder="Product description"></textarea>
                            </div>
                        </div>
                    )}

                    {/* Step 2: Stock Listing Information */}
                    {activeStep === 2 && (
                        <Step2 
                            data={formData} 
                            setData={setFormData} 
                            theme={theme} 
                            portions={portions}
                            setPortions={setPortions}
                        />
                    )}

                    {/* Step 3: Stock Information */}
                    {activeStep === 3 && (
                         <Step3
                            data={formData}
                            handleInputChange={handleInputChange}
                            handleStockCalculation={handleStockCalculation}
                            theme={theme}
                            portions={portions}
                         />
                    )}

                </div>

                <div className={`flex justify-between items-center p-6 border-t rounded-b-lg ${theme === 'dark' ? 'border-slate-700 bg-black/50' : 'border-slate-200 bg-slate-100'}`}>
                    {activeStep > 1 ? (
                        <button onClick={handleBack} className={`px-6 py-2.5 text-sm font-medium border rounded-md shadow-sm ${theme === 'dark' ? 'text-slate-300 bg-transparent border-slate-600 hover:bg-slate-700' : 'text-slate-700 bg-white border-slate-300 hover:bg-slate-50'}`}>
                            <Icon name="chevron-left" className="h-4 w-4 mr-1 inline" /> Back
                        </button>
                    ) : (
                         <button onClick={handleClose} className={`px-6 py-2.5 text-sm font-medium border rounded-md shadow-sm ${theme === 'dark' ? 'text-slate-300 bg-transparent border-slate-600 hover:bg-slate-700' : 'text-slate-700 bg-white border-slate-300 hover:bg-slate-50'}`}>
                            Cancel
                        </button>
                    )}

                    <div className="flex gap-2">
                        {activeStep === 2 && (
                            <button onClick={handleSaveFromStep2} className="px-6 py-2.5 text-sm font-semibold text-slate-900 bg-green-500 border border-transparent rounded-md shadow-sm hover:bg-green-600 flex items-center">
                                <Icon name="check-circle" className="h-4 w-4 mr-2" /> Save
                            </button>
                        )}

                        {activeStep < 3 ? (
                            <button onClick={handleNext} className="px-6 py-2.5 text-sm font-semibold text-slate-900 bg-yellow-500 border border-transparent rounded-md shadow-sm hover:bg-yellow-600 flex items-center">
                                Next <Icon name="chevron-right" className="h-4 w-4 ml-1" />
                            </button>
                        ) : (
                            <button onClick={handleSave} className="px-6 py-2.5 text-sm font-semibold text-slate-900 bg-yellow-500 border border-transparent rounded-md shadow-sm hover:bg-yellow-600 flex items-center">
                                <Icon name="check-circle" className="h-4 w-4 mr-2" /> Save Stock
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

// Extracted Step 2 Component for detailed portion editing
const Step2 = ({ data, setData, theme, portions, setPortions }: { 
    data: any, 
    setData: Function, 
    theme: Theme,
    portions: Portion[],
    setPortions: React.Dispatch<React.SetStateAction<Portion[]>>
}) => {
    const inputClass = `w-full rounded-md border shadow-sm px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200 placeholder-slate-500' : 'bg-white border-slate-300 text-slate-900 placeholder-slate-400'}`;
    const labelClass = `block text-sm font-medium mb-1 ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`;

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                    <label className={labelClass}>Product</label>
                    <input type="text" value={data.productName} disabled className={`${inputClass} opacity-60 cursor-not-allowed`} />
                </div>
                <div>
                    <label className={labelClass}>Custom Name</label>
                    <input type="text" name="customName" value={data.customName} onChange={(e) => setData({ ...data, customName: e.target.value })} className={inputClass} />
                </div>
            </div>

            <div>
                <label className={labelClass}>Reporting unit <span className="text-red-500">*</span></label>
                <select name="reportUnit" value={data.reportUnit} onChange={(e) => setData({ ...data, reportUnit: e.target.value })} className={inputClass}>
                    <option value="">Select a reporting unit</option>
                    {portions.filter(p => p.isSelected).map(p => <option key={p.id} value={p.name}>{p.name}</option>)}
                </select>
            </div>

            <div>
                <label className={labelClass}>Product units <span className="text-red-500">*</span></label>
                <div className="flex flex-wrap gap-2 mt-1 mb-3">
                    {portions.map((portion, index) => (
                        <button
                            key={index}
                            type="button"
                            onClick={() => {
                                const newPortions = [...portions];
                                newPortions[index].isSelected = !newPortions[index].isSelected;
                                setPortions(newPortions);
                            }}
                            className={`px-4 py-2 text-sm rounded border transition-colors ${
                                portion.isSelected
                                ? 'bg-yellow-400 text-slate-900 border-yellow-500 font-medium' 
                                : (theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-300 hover:bg-slate-700' : 'bg-white border-slate-300 text-slate-700 hover:bg-slate-100')
                            }`}
                        >
                            {portion.name}
                        </button>
                    ))}
                </div>

                {/* List of selected portions with detailed inputs */}
                <div className="space-y-3">
                    {portions.filter(p => p.isSelected).map((portion, index) => (
                         <div key={portion.id} className={`grid grid-cols-[2fr_1fr_auto] gap-4 items-center p-3 border rounded-md ${theme === 'dark' ? 'bg-slate-800/50 border-slate-700' : 'bg-slate-50 border-slate-200'}`}>
                             <div>
                                 <input 
                                    type="text" 
                                    value={portion.name} 
                                    onChange={(e) => {
                                        const newName = e.target.value;
                                        const newPortions = portions.map(p => p.id === portion.id ? { ...p, name: newName } : p);
                                        setPortions(newPortions);
                                        // Update main selection if this was the default
                                        if (data.containerPortion === portion.name) {
                                             setData({ ...data, containerPortion: newName });
                                        }
                                    }}
                                    className={inputClass} 
                                    placeholder="Portion Name"
                                />
                             </div>
                             <div>
                                 <input 
                                    type="number" 
                                    value={portion.price || ''} 
                                    placeholder="Price"
                                    onChange={(e) => {
                                        const newPrice = parseFloat(e.target.value) || 0;
                                        const newPortions = portions.map(p => p.id === portion.id ? { ...p, price: newPrice } : p);
                                        setPortions(newPortions);
                                        // If this is default, update main price
                                        if (data.containerPortion === portion.name) {
                                             setData({ ...data, unitPrice: e.target.value });
                                        }
                                    }}
                                    className={`${inputClass} text-right`} 
                                />
                             </div>
                             <div className="flex items-center justify-center px-2">
                                <input 
                                    type="radio" 
                                    name="defaultPortion"
                                    checked={data.containerPortion === portion.name} 
                                    onChange={() => {
                                        setData({ ...data, containerPortion: portion.name, unitPrice: portion.price.toString() });
                                    }}
                                    className="w-4 h-4 text-yellow-500 bg-gray-100 border-gray-300 focus:ring-yellow-500 dark:focus:ring-yellow-600 dark:ring-offset-gray-800 focus:ring-2 dark:bg-gray-700 dark:border-gray-600 cursor-pointer"
                                />
                             </div>
                        </div>
                    ))}
                </div>
            </div>

            <div>
                <label className={labelClass}>Remarks</label>
                <textarea name="listingRemarks" value={data.listingRemarks} onChange={(e) => setData({...data, listingRemarks: e.target.value})} className={inputClass} rows={3}></textarea>
            </div>
        </div>
    );
};

// New Step 3 Component with detailed layout
const Step3 = ({ data, handleInputChange, handleStockCalculation, theme, portions }: any) => {
    const inputClass = `w-full rounded-md border shadow-sm px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200 placeholder-slate-500' : 'bg-white border-slate-300 text-slate-900 placeholder-slate-400'}`;
    const labelClass = `block text-sm font-medium mb-1 ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`;

    // Show available stock units based on portions defined in step 2
    const stockUnitOptions = portions && portions.length > 0 
        ? portions.map((p: any) => <option key={p.name} value={p.name}>{p.name}</option>)
        : availableProductUnits.map(u => <option key={u} value={u}>{u}</option>);

    return (
        <div className="space-y-4">
             {/* Stock Unit */}
            <div>
                <label className={labelClass}>Stock Unit<span className="text-red-500">*</span></label>
                <select name="stockUnit" value={data.stockUnit} onChange={handleInputChange} className={inputClass}>
                    <option value="">Select stocking unit</option>
                    {stockUnitOptions}
                </select>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {/* Qty */}
                <div>
                    <label className={labelClass}>Qty <span className="text-red-500">*</span></label>
                    <input 
                        type="number" 
                        name="quantity" 
                        value={data.quantity} 
                        onChange={(e) => handleStockCalculation('quantity', e.target.value)} 
                        className={inputClass} 
                    />
                </div>
                 {/* Purchase Price */}
                <div>
                    <label className={labelClass}>Purchase price<span className="text-red-500">*</span></label>
                    <input 
                        type="number" 
                        name="buyingPrice" 
                        value={data.buyingPrice} 
                        onChange={(e) => handleStockCalculation('buyingPrice', e.target.value)} 
                        className={inputClass} 
                    />
                </div>
            </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {/* Unit Price (Cost or Selling - here used for calc) */}
                <div>
                    <label className={labelClass}>Unit price</label>
                    <input 
                        type="number" 
                        name="unitPrice" 
                        value={data.unitPrice} 
                        onChange={(e) => handleStockCalculation('unitPrice', e.target.value)} 
                        className={inputClass} 
                        placeholder="0" 
                    />
                </div>
                 {/* Purchase Date */}
                <div>
                    <label className={labelClass}>Purchase date<span className="text-red-500">*</span></label>
                    <input type="date" name="date" value={data.date} onChange={handleInputChange} className={inputClass} />
                </div>
            </div>

            {(data.hasBatchNumber || data.hasExpiryDate) && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {data.hasBatchNumber && (
                        <div>
                            <label className={labelClass}>Batch no</label>
                            <input type="text" name="batchNumber" value={data.batchNumber} onChange={handleInputChange} className={inputClass} />
                        </div>
                    )}
                    {data.hasExpiryDate && (
                        <div>
                            <label className={labelClass}>Expiry date</label>
                            <input type="date" name="expiryDate" value={data.expiryDate} onChange={handleInputChange} className={inputClass} />
                        </div>
                    )}
                </div>
            )}

             {/* Supplier & Invoice */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                    <label className={labelClass}>Supplier</label>
                    <select name="supplier" value={data.supplier} onChange={handleInputChange} className={inputClass}>
                        {suppliers.map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                </div>
                <div>
                    <label className={labelClass}>Invoice Number</label>
                    <input type="text" name="invoiceNumber" value={data.invoiceNumber} onChange={handleInputChange} className={inputClass} placeholder="Optional" />
                </div>
            </div>

             {/* Remarks */}
            <div>
                <label className={labelClass}>Remarks</label>
                <textarea name="listingRemarks" value={data.listingRemarks} onChange={handleInputChange} className={inputClass} rows={3}></textarea>
            </div>
        </div>
    )
}

export default OpeningStockModal;
